import dis
import sys
from functools import wraps

import pybamm
from qa_instances_eval.pybamm_qa.parameter_values_update_def_use_intersection_suite.files.tests.qa.parameter_values_update_def_use_intersection_suite_test import (
    TestParameterValuesUpdateDefUseIntersectionQA,
)

tracked = {
    "check_already_exists",
    "check_conflict",
    "data",
    "func_name",
    "name",
    "path",
    "value",
    "values",
}

update_func = pybamm.parameters.parameter_values.ParameterValues.update
code = update_func.__code__

# Map bytecode offset -> (opname, argval, line)
inst_by_offset = {}
current_line = code.co_firstlineno
for inst in dis.get_instructions(update_func):
    if inst.starts_line is not None:
        current_line = inst.starts_line
    inst_by_offset[inst.offset] = (inst.opname, inst.argval, current_line)

class Collector:
    def __init__(self):
        self.calls = []
        self.active = {}

    def tracer(self, frame, event, arg):
        if event == "call" and frame.f_code is code:
            state = {
                "current_def": {
                    "values": 242,
                    "check_conflict": 242,
                    "check_already_exists": 242,
                    "path": 242,
                },
                "pairs": set(),
            }
            self.active[id(frame)] = state
            frame.f_trace_opcodes = True
            return self.tracer

        fid = id(frame)
        if fid not in self.active:
            return self.tracer

        state = self.active[fid]

        if event == "opcode":
            inst = inst_by_offset.get(frame.f_lasti)
            if inst is None:
                return self.tracer
            opname, argval, line = inst
            if argval in tracked:
                if opname.startswith("LOAD_FAST"):
                    d = state["current_def"].get(argval)
                    if d is not None:
                        state["pairs"].add((argval, d, line))
                elif opname.startswith("STORE_FAST"):
                    state["current_def"][argval] = line
        elif event == "return":
            self.calls.append(state["pairs"])
            del self.active[fid]

        return self.tracer

collector = Collector()

def run_one(method_name):
    t = TestParameterValuesUpdateDefUseIntersectionQA()
    before = len(collector.calls)
    sys.settrace(collector.tracer)
    try:
        getattr(t, method_name)()
    finally:
        sys.settrace(None)
    after = len(collector.calls)
    if after != before + 1:
        raise RuntimeError(f"Expected exactly one update call for {method_name}, got {after-before}")
    return collector.calls[-1]

order = [f"test_case_{i:02d}" for i in range(1, 11)]
per_test = {}
for name in order:
    per_test[name] = run_one(name)

intersection = set.intersection(*(per_test[name] for name in order))

print("INTERSECTION")
for var, d, u in sorted(intersection, key=lambda x: (x[0], x[1], x[2])):
    print(var, d, u)

print("COUNTS")
for name in order:
    print(name, len(per_test[name]))
